class ValidationError extends Error {
  constructor(message, field) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}

function parseUser(json) {
  const user = JSON.parse(json);
  if (!user.name) throw new ValidationError("Name is required", "name");
  return user;
}

for (const input of ['{"name":"Asha"}', '{"age":3}', "{bad json}"]) {
  try {
    console.log("OK:", parseUser(input).name);
  } catch (e) {
    if (e instanceof ValidationError) console.log("Validation:", e.field, "-", e.message);
    else console.log("Other:", e.name);
  } finally {
    console.log("done with", input.slice(0, 8));
  }
}

