examples.js:
let seconds = 0;
let intervalId = null;
const display = document.getElementById("countDown");
const log = document.getElementById("log");

function start() {
  if (intervalId) return;               // avoid double intervals
  intervalId = setInterval(() => {
    seconds++;
    display.textContent = seconds;
  }, 1000);
}
function stop() {
  clearInterval(intervalId);
  intervalId = null;
  const p = document.createElement("p");
  p.textContent = "Stopped at " + seconds + "s";
  log.append(p);
}
function reset() {
  stop();
  seconds = 0;
  display.textContent = 0;
  log.innerHTML = "";
}
document.getElementById("start").addEventListener("click", start);
document.getElementById("stop").addEventListener("click", stop);
document.getElementById("reset").addEventListener("click", reset);

topics.description:
A **callback** is a function you pass to be called when an asynchronous task completes. Before Promises, callbacks were the only way to sequence async work.

### The problem
When each step depends on the previous one, callbacks nest deeper and deeper - the **pyramid of doom** or **callback hell**:

```js
getUser(id, (err, user) => {
  getPosts(user.id, (err, posts) => {
    getComments(posts[0].id, (err, comments) => {
      // ...
    });
  });
});
```

### Why it is bad
- Hard to read and reason about.
- Error handling must be repeated at every level.
- Hard to run steps in parallel or return a value.
- **Inversion of control**: you trust a third-party function to call your callback once, and at the right time.

### Error-first callbacks
Node.js convention: the first parameter is the error: `callback(err, data)`. Always check `err` first.

### Ways out
1. **Name your functions** and keep them flat.
2. **Promises** - chain with `.then()`.
3. **async/await** - write async code that looks synchronous.
4. Use `Promise.all` for parallel work.

### Promisify
Wrap an old callback API into a promise:
```js
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
```
Node has `util.promisify` for error-first callbacks.

examples.code:
// callback hell
function step(msg, cb) { setTimeout(() => { console.log(msg); cb(); }, 5); }
step("cb 1: name", () => {
  step("cb 2: middle name", () => {
    step("cb 3: last name", () => {
      console.log("callbacks finished");
      flat();
    });
  });
});

// the same with promises and async/await
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const stepP = async (msg) => { await wait(5); console.log(msg); };
async function flat() {
  await stepP("await 1: name");
  await stepP("await 2: middle name");
  await stepP("await 3: last name");
  console.log("flat code finished");
}

const enrollStudent = (name) =>
  new Promise((resolve, reject) => {
    setTimeout(() => {
      name ? resolve(`Enrollment successful for ${name}`) : reject(new Error("Name missing"));
    }, 10);
  });

enrollStudent("Vinod")
  .then((msg) => { console.log(msg); return msg.length; })
  .then((len) => console.log("length:", len))
  .catch((e) => console.log("error:", e.message))
  .finally(() => console.log("1. process completed"));

enrollStudent("")
  .then((m) => console.log(m))
  .catch((e) => console.log("error:", e.message))
  .finally(() => console.log("2. process completed"));

console.log("sync code finishes first");

const delay = (ms, value, fail = false) =>
  new Promise((res, rej) => setTimeout(() => (fail ? rej(value) : res(value)), ms));

const p1 = () => delay(30, "First");
const p2 = () => delay(10, "Failed", true);
const p3 = () => delay(20, "Third");

(async () => {
  console.log("all:", await Promise.all([p1(), p3()]));
  try { await Promise.all([p1(), p2(), p3()]); }
  catch (e) { console.log("all rejected with:", e); }

  const settled = await Promise.allSettled([p1(), p2(), p3()]);
  console.log("allSettled:", settled.map((r) => r.status + ":" + (r.value ?? r.reason)));

  console.log("race:", await Promise.race([p1(), p3()]));
  console.log("any:", await Promise.any([p2(), p1(), p3()]));
})();

topics.description:
`async`/`await` (ES2017) is syntax built on promises that makes async code read like synchronous code.

### async functions
```js
async function getData() {
  return 42;          // automatically wrapped: returns Promise<42>
}
```
An `async` function **always returns a promise**. Thrown errors become rejections.

### await
`await promise` pauses **only that async function** until the promise settles and gives you its value (or throws the rejection). The rest of the program keeps running. `await` works inside `async` functions and at the top level of ES modules.

```js
async function load() {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error("HTTP " + res.status);
    const data = await res.json();
    return data;
  } catch (err) {
    console.error(err);
  } finally {
    hideSpinner();
  }
}
```

### Sequential vs parallel
```js
const a = await taskA();      // waits
const b = await taskB();      // starts after A
const [x, y] = await Promise.all([taskA(), taskB()]); // parallel
```

### Loops
- `for...of` with `await` runs steps in order.
- `array.forEach(async ...)` does **not** wait. Use `for...of` or `await Promise.all(arr.map(async ...))`.

### Under the hood
Code after `await` is scheduled as a **microtask** once the promise settles.

### Tips
- Wrap awaits in `try/catch`.
- Do not use `await` when you do not need the value; return the promise.
- Avoid `async` for functions that do nothing asynchronous.

examples.code:
const wait = (ms, v) => new Promise((r) => setTimeout(() => r(v), ms));

async function sequential() {
  const t = Date.now();
  const a = await wait(50, "A");
  const b = await wait(50, "B");
  return [a, b, Math.round((Date.now() - t) / 50) * 50 + "ms"];
}
async function parallel() {
  const t = Date.now();
  const [a, b] = await Promise.all([wait(50, "A"), wait(50, "B")]);
  return [a, b, Math.round((Date.now() - t) / 50) * 50 + "ms"];
}
async function failing() {
  try {
    await Promise.reject(new Error("API is down"));
  } catch (e) {
    return "caught: " + e.message;
  }
}
(async () => {
  console.log("sequential", await sequential());
  console.log("parallel", await parallel());
  console.log(await failing());
  console.log(await (async () => 42)(), (async () => 1)() instanceof Promise);
})();

